using UnityEngine;

public class DontDestroy : MonoBehaviour
{
    private void Awake()
    {
        // 이 오브젝트가 이미 존재하는지 확인
        if (FindObjectsByType<DontDestroy>(FindObjectsSortMode.None).Length > 1)
        {
            Destroy(gameObject); // 중복된 오브젝트는 삭제
        }
        else
        {
            DontDestroyOnLoad(gameObject); // 이 오브젝트를 파괴하지 않음
        }
    }
    private void Start()
    {
        SetResolution();
    }
    private void OnDestroy()
    {
        // 오브젝트가 파괴될 때 로그 출력
        Debug.Log("DontDestroy 오브젝트가 파괴되었습니다.");
    }

    private void OnApplicationQuit()
    {
        // 애플리케이션이 종료될 때 로그 출력
        Debug.Log("애플리케이션이 종료됩니다.");
    }

    //해상도에 따른 화면 비율 고정 9:16 비율인 세로 비율로  // 남는영역은 검은색으로 처리
    private void SetResolution()
    {
        float targetAspect = 9f / 16f;
        float windowAspect = (float)Screen.width / (float)Screen.height;
        float scaleHeight = windowAspect / targetAspect;

        Camera camera = Camera.main;
        if (camera == null) return;

        if (scaleHeight < 1.0f)
        {
            Rect rect = camera.rect;
            rect.width = 1.0f;
            rect.height = scaleHeight;
            rect.x = 0;
            rect.y = (1.0f - scaleHeight) / 2.0f;
            camera.rect = rect;
        }
        else
        {
            float scaleWidth = 1.0f / scaleHeight;
            Rect rect = camera.rect;
            rect.width = scaleWidth;
            rect.height = 1.0f;
            rect.x = (1.0f - scaleWidth) / 2.0f;
            rect.y = 0;
            camera.rect = rect;
        }
    }


}

using UnityEngine;

public class DontDestroy : MonoBehaviour
{
    private void Awake()
    {
        // 이 오브젝트가 이미 존재하는지 확인
        if (FindObjectsByType<DontDestroy>(FindObjectsSortMode.None).Length > 1)
        {
            Destroy(gameObject); // 중복된 오브젝트는 삭제
        }
        else
        {
            DontDestroyOnLoad(gameObject); // 이 오브젝트를 파괴하지 않음
        }
    }
    private void Start()
    {
        SetResolution();
    }
    private void OnDestroy()
    {
        // 오브젝트가 파괴될 때 로그 출력
        Debug.Log("DontDestroy 오브젝트가 파괴되었습니다.");
    }

    private void OnApplicationQuit()
    {
        // 애플리케이션이 종료될 때 로그 출력
        Debug.Log("애플리케이션이 종료됩니다.");
    }

    //해상도에 따른 화면 비율 고정 9:16 비율인 세로 비율로  // 남는영역은 검은색으로 처리
    private void SetResolution()
    {
        float targetAspect = 9f / 16f;
        float windowAspect = (float)Screen.width / (float)Screen.height;
        float scaleHeight = windowAspect / targetAspect;

        Camera camera = Camera.main;
        if (camera == null) return;

        camera.backgroundColor = Color.black; // 남는 영역을 검은색으로 처리
        camera.clearFlags = CameraClearFlags.SolidColor;

        if (scaleHeight < 1.0f)
        {
            Rect rect = camera.rect;
            rect.width = 1.0f;
            rect.height = scaleHeight;
            rect.x = 0;
            rect.y = (1.0f - scaleHeight) / 2.0f;
            camera.rect = rect;
        }
        else
        {
            float scaleWidth = 1.0f / scaleHeight;
            Rect rect = camera.rect;
            rect.width = scaleWidth;
            rect.height = 1.0f;
            rect.x = (1.0f - scaleWidth) / 2.0f;
            rect.y = 0;
            camera.rect = rect;
        }
    }


}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

namespace DogGuns_Games
{
    public class SceneLoader : MonoBehaviour
    {
        protected static SceneLoader instance;

        // 씬 이름 상수들
        public const string INTRO_SCENE = "IntroScene";
        public const string LOBBY_SCENE = "LobbyScene";
        public const string RUN_GAME_SCENE = "RunGame";
        public const string VAMSER_LIKE_SCENE = "VamSerlike";

        public static SceneLoader Instance // 오타 수정: Instace -> Instance
        {
            get
            {
                if (instance == null)
                {
                    var obj = FindAnyObjectByType<SceneLoader>();
                    if (obj != null)
                    {
                        instance = obj;
                    }
                    else
                    {
                        instance = Create();
                    }
                }

                return instance;
            }
            private set { instance = value; }
        }

        [SerializeField] private CanvasGroup sceneLoadferCanvasGroup;
        [SerializeField] private Slider progressbar;

        [Header("Scene References")]
        [SerializeField] private SceneReference[] sceneReferences;

        [System.Serializable]
        public class SceneReference
        {
            public string sceneName;

            #if UNITY_EDITOR
            [SerializeField] private UnityEditor.SceneAsset sceneAsset;

            public UnityEditor.SceneAsset SceneAsset
            {
                get => sceneAsset;
                set
                {
                    sceneAsset = value;
                    sceneName = sceneAsset != null ? sceneAsset.name : "";
                }
            }
            #endif
        }


        private string loadSceneName;

        public static SceneLoader Create()
        {
            var SeneLoadprefeb = Resources.Load<SceneLoader>("SceneLoader");
            return Instantiate(SeneLoadprefeb);
        }

        private void Awake()
        {
            if (instance != this)
            {
                Destroy(gameObject);
                return;
            }

            DontDestroyOnLoad(gameObject);
        }

        /// <summary>
        /// 로비 씬으로 이동합니다.
        /// </summary>
        public void LoadLobbyScene()
        {
            LoadScene(LOBBY_SCENE);
        }

        /// <summary>
        /// 게임 씬으로 이동합니다.
        /// </summary>
        public void LoadGameScene()
        {
            LoadScene(RUN_GAME_SCENE);
        }

        /// <summary>
        /// VamSerLike 씬으로 이동합니다.
        /// </summary>
        public void LoadVamSerLikeScene()
        {
            LoadScene(VAMSER_LIKE_SCENE);
        }

        /// <summary>
        /// 인트로 씬으로 이동합니다.
        /// </summary>
        public void LoadIntroScene()
        {
            LoadScene(INTRO_SCENE);
        }

        public void LoadScene(string SceneName)
        {
            // 씬이 빌드에 포함되어 있는지 확인
            if (!IsSceneInBuild(SceneName))
            {
                Debug.LogError($"씬 '{SceneName}'이 빌드 설정에 포함되어 있지 않습니다!");
                return;
            }

            gameObject.SetActive(true);
            SceneManager.sceneLoaded += LoadSceneEnd;
            loadSceneName = SceneName;
            StartCoroutine(Load(SceneName));
            Debug.Log($"씬 변경 시작: {SceneName}");
        }

        /// <summary>
        /// 씬이 빌드에 포함되어 있는지 확인합니다.
        /// </summary>
        private bool IsSceneInBuild(string sceneName)
        {
            for (int i = 0; i < SceneManager.sceneCountInBuildSettings; i++)
            {
                string scenePath = SceneUtility.GetScenePathByBuildIndex(i);
                string sceneNameInBuild = System.IO.Path.GetFileNameWithoutExtension(scenePath);
                if (sceneNameInBuild == sceneName)
                {
                    return true;
                }
            }
            return false;
        }

        /// <summary>
        /// SceneReference를 통해 씬을 로드합니다.
        /// </summary>
        public void LoadScene(SceneReference sceneRef)
        {
            if (sceneRef != null && !string.IsNullOrEmpty(sceneRef.sceneName))
            {
                LoadScene(sceneRef.sceneName);
            }
            else
            {
                Debug.LogError("SceneReference가 유효하지 않습니다!");
            }
        }


        /// <summary>
        /// 씬 이름으로 SceneReference를 찾습니다.
        /// </summary>
        public SceneReference FindSceneReference(string sceneName)
        {
            if (sceneReferences != null)
            {
                foreach (var sceneRef in sceneReferences)
                {
                    if (sceneRef.sceneName == sceneName)
                        return sceneRef;
                }
            }
            return null;
        }

        private IEnumerator Load(string sceneName)
        {
            progressbar.value = 0f;
            yield return StartCoroutine(Fade(true));

            AsyncOperation op = SceneManager.LoadSceneAsync(sceneName);
            op.allowSceneActivation = false;

            float timer = 0.0f;
            while (!op.isDone)
            {
                yield return null;
                timer += Time.unscaledDeltaTime;
                if (op.progress < 0.9f)
                {
                    float targetProgress = Mathf.Lerp(progressbar.value, op.progress, timer);
                    progressbar.value = targetProgress;
                    if (progressbar.value >= op.progress)
                    {
                        timer = 0f;
                    }
                }
                else
                {
                    float targetProgress = Mathf.Lerp(progressbar.value, 1f, timer);
                    progressbar.value = targetProgress;
                    if (progressbar.value >= 0.9999f)
                    {
                        op.allowSceneActivation = true;
                        yield break;
                    }
                }
            }
        }


        private void LoadSceneEnd(Scene scene, LoadSceneMode loadSceneMode)
        {
            if (scene.name == loadSceneName)
            {
                StartCoroutine(Fade(false));
                SceneManager.sceneLoaded -= LoadSceneEnd;
            }
        }

        private IEnumerator Fade(bool isFadeIn)
        {
            float timer = 0f;

            while (timer <= 1f)
            {
                yield return null;
                timer += Time.unscaledDeltaTime * 2f;
                sceneLoadferCanvasGroup.alpha = Mathf.Lerp(isFadeIn ? 0 : 1, isFadeIn ? 1 : 0, timer);
            }

            if (!isFadeIn)
            {
                gameObject.SetActive(false);
            }
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

namespace DogGuns_Games
{
    public class SceneLoader : MonoBehaviour
    {
        protected static SceneLoader instance;

        // 씬 이름 상수들
        public const string INTRO_SCENE = "IntroScene";
        public const string LOBBY_SCENE = "LobbyScene";
        public const string RUN_GAME_SCENE = "RunGame";
        public const string VAMSER_LIKE_SCENE = "VamSerlike";

        public static SceneLoader Instance // 오타 수정: Instace -> Instance
        {
            get
            {
                if (instance == null)
                {
                    var obj = FindAnyObjectByType<SceneLoader>();
                    if (obj != null)
                    {
                        instance = obj;
                    }
                    else
                    {
                        instance = Create();
                    }
                }

                return instance;
            }
            private set { instance = value; }
        }

        [SerializeField] private CanvasGroup sceneLoadferCanvasGroup;
        [SerializeField] private Slider progressbar;

        [Header("Scene References")]
        [SerializeField] private SceneReference[] sceneReferences;

        [System.Serializable]
        public class SceneReference
        {
            public string sceneName;

            #if UNITY_EDITOR
            [SerializeField] private UnityEditor.SceneAsset sceneAsset;

            public UnityEditor.SceneAsset SceneAsset
            {
                get => sceneAsset;
                set
                {
                    sceneAsset = value;
                    sceneName = sceneAsset != null ? sceneAsset.name : "";
                }
            }
            #endif
        }


        private string loadSceneName;

        public static SceneLoader Create(SceneLoader prefab = null)
        {
            if (prefab == null)
            {
                Debug.LogError("SceneLoader 프리팹이 지정되지 않았습니다.");
                return null;
            }
            return Instantiate(prefab);
        }

        private void Awake()
        {
            if (instance != this)
            {
                Destroy(gameObject);
                return;
            }

            DontDestroyOnLoad(gameObject);
        }

        /// <summary>
        /// 로비 씬으로 이동합니다.
        /// </summary>
        public void LoadLobbyScene()
        {
            LoadScene(LOBBY_SCENE);
        }

        /// <summary>
        /// 게임 씬으로 이동합니다.
        /// </summary>
        public void LoadGameScene()
        {
            LoadScene(RUN_GAME_SCENE);
        }

        /// <summary>
        /// VamSerLike 씬으로 이동합니다.
        /// </summary>
        public void LoadVamSerLikeScene()
        {
            LoadScene(VAMSER_LIKE_SCENE);
        }

        /// <summary>
        /// 인트로 씬으로 이동합니다.
        /// </summary>
        public void LoadIntroScene()
        {
            LoadScene(INTRO_SCENE);
        }

        public void LoadScene(string SceneName)
        {
            // 씬이 빌드에 포함되어 있는지 확인
            if (!IsSceneInBuild(SceneName))
            {
                Debug.LogError($"씬 '{SceneName}'이 빌드 설정에 포함되어 있지 않습니다!");
                return;
            }

            gameObject.SetActive(true);
            SceneManager.sceneLoaded += LoadSceneEnd;
            loadSceneName = SceneName;
            StartCoroutine(Load(SceneName));
            Debug.Log($"씬 변경 시작: {SceneName}");
        }

        /// <summary>
        /// 씬이 빌드에 포함되어 있는지 확인합니다.
        /// </summary>
        private bool IsSceneInBuild(string sceneName)
        {
            for (int i = 0; i < SceneManager.sceneCountInBuildSettings; i++)
            {
                string scenePath = SceneUtility.GetScenePathByBuildIndex(i);
                string sceneNameInBuild = System.IO.Path.GetFileNameWithoutExtension(scenePath);
                if (sceneNameInBuild == sceneName)
                {
                    return true;
                }
            }
            return false;
        }

        /// <summary>
        /// SceneReference를 통해 씬을 로드합니다.
        /// </summary>
        public void LoadScene(SceneReference sceneRef)
        {
            if (sceneRef != null && !string.IsNullOrEmpty(sceneRef.sceneName))
            {
                LoadScene(sceneRef.sceneName);
            }
            else
            {
                Debug.LogError("SceneReference가 유효하지 않습니다!");
            }
        }


        /// <summary>
        /// 씬 이름으로 SceneReference를 찾습니다.
        /// </summary>
        public SceneReference FindSceneReference(string sceneName)
        {
            if (sceneReferences != null)
            {
                foreach (var sceneRef in sceneReferences)
                {
                    if (sceneRef.sceneName == sceneName)
                        return sceneRef;
                }
            }
            return null;
        }

        private IEnumerator Load(string sceneName)
        {
            progressbar.value = 0f;
            yield return StartCoroutine(Fade(true));

            AsyncOperation op = SceneManager.LoadSceneAsync(sceneName);
            op.allowSceneActivation = false;

            float timer = 0.0f;
            while (!op.isDone)
            {
                yield return null;
                timer += Time.unscaledDeltaTime;
                if (op.progress < 0.9f)
                {
                    float targetProgress = Mathf.Lerp(progressbar.value, op.progress, timer);
                    progressbar.value = targetProgress;
                    if (progressbar.value >= op.progress)
                    {
                        timer = 0f;
                    }
                }
                else
                {
                    float targetProgress = Mathf.Lerp(progressbar.value, 1f, timer);
                    progressbar.value = targetProgress;
                    if (progressbar.value >= 0.9999f)
                    {
                        op.allowSceneActivation = true;
                        yield break;
                    }
                }
            }
        }


        private void LoadSceneEnd(Scene scene, LoadSceneMode loadSceneMode)
        {
            if (scene.name == loadSceneName)
            {
                StartCoroutine(Fade(false));
                SceneManager.sceneLoaded -= LoadSceneEnd;
            }
        }

        private IEnumerator Fade(bool isFadeIn)
        {
            float timer = 0f;

            while (timer <= 1f)
            {
                yield return null;
                timer += Time.unscaledDeltaTime * 2f;
                sceneLoadferCanvasGroup.alpha = Mathf.Lerp(isFadeIn ? 0 : 1, isFadeIn ? 1 : 0, timer);
            }

            if (!isFadeIn)
            {
                gameObject.SetActive(false);
            }
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;


public class SoundManager : MonoBehaviour
{
    #region 싱글톤

    private static SoundManager _instance;

    public static SoundManager Instance
    {
        get
        {
            if (_instance == null)
            {
                // 씬에서 SoundManager를 찾아봅니다.
                _instance = FindFirstObjectByType<SoundManager>();
                // 씬에 SoundManager가 없다면, 새로 생성하지 않고 경고를 출력합니다.
                // SoundManager는 씬에 미리 배치하고 SoundData를 할당해야 합니다.
                if (_instance == null)
                {
                    Debug.LogError(
                        "SoundManager instance not found in the scene. Please add SoundManager to your scene and assign SoundData.");
                }
            }

            return _instance;
        }
    }

    #endregion

    #region 변수 및 필드

    [SerializeField] private SoundData soundData; // 인스펙터에서 할당할 SoundData

    [SerializeField] private SettingsData_oBJ settingsData;

    AudioSource[] _audioSources = new AudioSource[(int)Sound.Max];
    Dictionary<string, AudioClip> _audioClips = new Dictionary<string, AudioClip>();
    private float _effectsoundVolum = 1.0f;
    private float _bgmSoundVolum = 1.0f;

    #endregion

    #region 정적 메서드

    // 정적 호출 지원
    public static void PlaySound(Sound type, string clipName, bool loop = false, float pitch = 1.0f)
    {
        Instance.Play(clipName, type, pitch, loop);
    }

    public static void PlaySound(Sound type, SoundKeys clipKey, bool loop = false, float pitch = 1.0f)
    {
        Instance.Play(clipKey.ToString(), type, pitch, loop);
    }

    #endregion

    #region 초기화 메서드

    private void Awake()
    {
        if (_instance != null && _instance != this)
        {
            Destroy(gameObject);
            return;
        }

        _instance = this;
        Init();
        DontDestroyOnLoad(gameObject);
    }

    public void Init()
    {
        if (_audioSources[0] != null) return; // 이미 초기화된 경우 중복 방지

        GameObject root = new GameObject { name = "Sound" };
        root.transform.parent = transform; // SoundManager의 자식으로 관리

        string[] SoundNames = System.Enum.GetNames(typeof(Sound));
        for (int i = 0; i < SoundNames.Length - 1; i++)
        {
            GameObject go = new GameObject { name = SoundNames[i] };
            _audioSources[i] = go.AddComponent<AudioSource>();
            go.transform.parent = root.transform;
        }

        _audioSources[(int)Sound.BGM].loop = true;

        // 할당된 SoundData에서 오디오 클립 초기화
        if (soundData != null)
        {
            foreach (var audioInfo in soundData.audioClips)
            {
                if (!_audioClips.ContainsKey(audioInfo.key))
                {
                    _audioClips.Add(audioInfo.key, audioInfo.clip);
                }
            }
        }
        else
        {
            Debug.LogError("SoundData가 SoundManager에 할당되지 않았습니다. 인스펙터에서 할당해주세요.");
        }

        LoadSoundSetting();
    }


    public void LoadSoundSetting()
    {

        settingsData.LoadSettings();

        if (settingsData == null)
        {
            Debug.LogError("SettingsData_oBJ가 SoundManager에 할당되지 않았습니다. 인스펙터에서 할당해주세요.");
            return;
        }
        // 배경음과 효과음 볼륨 설정
        _bgmSoundVolum = settingsData.backgroundSoundVolume;
        _effectsoundVolum = settingsData.effectSoundVolume;

        // 초기 볼륨 설정
        VolumSet(Sound.BGM, _bgmSoundVolum);
        VolumSet(Sound.SFX, _effectsoundVolum);
    }

    public void Clear()
    {
        foreach (AudioSource audioSource in _audioSources)
        {
            if (audioSource == null) continue;
            audioSource.clip = null;
            audioSource.Stop();
        }

        _audioClips.Clear();
    }

    #endregion

    #region 오디오 재생 메서드

    public void Play(AudioClip audioClip, Sound type = Sound.SFX, float pitch = 1.0f, bool loop = false)
    {
        if (audioClip == null)
            return;

        AudioSource audioSource = _audioSources[(int)type];
        if (audioSource == null) return;

        audioSource.pitch = pitch;

        if (type == Sound.BGM)
        {
            if (audioSource.isPlaying)
                audioSource.Stop();
            audioSource.volume = _bgmSoundVolum;
            audioSource.loop = loop;
            audioSource.clip = audioClip;
            audioSource.Play();
            //성공 로그 출력 
            Debug.Log($"Playing BGM: {audioClip.name} with volume: {_bgmSoundVolum}");
        }
        else // Effect
        {
            audioSource.volume = _effectsoundVolum;
            audioSource.loop = false;
            audioSource.PlayOneShot(audioClip);
        }
    }

    public void Play(string path, Sound type = Sound.SFX, float pitch = 1.0f, bool loop = false)
    {
        AudioClip audioClip = GetAudioClip(path);
        Play(audioClip, type, pitch, loop);
    }

    #endregion

    #region 유틸리티 메서드

    public void VolumSet(Sound type = Sound.SFX, float volum = 1.0f)
    {
        if (type == Sound.BGM)
        {
            _bgmSoundVolum = volum;
            // 현재 재생 중인 BGM의 볼륨을 즉시 업데이트
            if (_audioSources[(int)Sound.BGM] != null)
            {
                _audioSources[(int)Sound.BGM].volume = _bgmSoundVolum;
            }
        }
        else if (type == Sound.SFX)
        {
            _effectsoundVolum = volum;
            // SFX는 PlayOneShot을 사용하므로 다음 재생부터 적용됨

            if (_audioSources[(int)Sound.SFX] != null)
            {
                _audioSources[(int)Sound.SFX].volume = _effectsoundVolum;
            }

            //Debug.Log($"SFX volume updated to: {_effectsoundVolum}");
        }
    }

    AudioClip GetAudioClip(string key)
    {
        if (_audioClips.TryGetValue(key, out AudioClip audioClip))
        {
            return audioClip;
        }

        Debug.LogWarning($"AudioClip not found: {key}");
        return null;
    }

    #endregion
}

