        #region 플레이어 제어

        /// <summary>
        /// 플레이어 이동을 처리하는 메서드
        /// </summary>
        private void PlayerMovement()
        {
            // 플레이어 객체 유효성 검사
            if (player == null || playerCharactor == null)
            {
                // PlayerInit(); // 재귀 호출 및 로직 문제로 제거
                return;
            }

            // 이동 입력 및 위치 계산
            Vector3 moveDirection = GetJoystickInputDirection();
            Vector3 targetPosition = CalculateTargetPosition(moveDirection);

            // 실제 이동 처리
            MovePlayer(targetPosition);

            // 애니메이션 및 회전 처리
            UpdateAnimationState(moveDirection.magnitude);

            // 공격 처리
            TryAttack(moveDirection);

            // 캐릭터 회전 처리
            UpdateCharacterRotation(moveDirection);
        }

        /// <summary>
        /// 조이스틱 입력을 방향 벡터로 변환
        /// </summary>
        private Vector3 GetJoystickInputDirection()
        {
            return (Vector3.right * variableJoystick.Horizontal + Vector3.up * variableJoystick.Vertical);
        }

        /// <summary>
        /// 맵 범위를 고려한 목표 위치 계산
        /// </summary>
        private Vector3 CalculateTargetPosition(Vector3 moveDirection)
        {
            float deltaSpeed = playerCharactor.MoveSpeed * Time.deltaTime;
            Vector3 rawTargetPosition = player.transform.position + moveDirection * deltaSpeed;

            // 맵 경계 확인
            Bounds mapBounds = mapRange.bounds;

            // 맵 범위 내로 제한
            Vector3 clampedPosition = new Vector3(
                Mathf.Clamp(rawTargetPosition.x, mapBounds.min.x, mapBounds.max.x),
                Mathf.Clamp(rawTargetPosition.y, mapBounds.min.y, mapBounds.max.y),
                rawTargetPosition.z
            );

            return clampedPosition;
        }

        /// <summary>
        /// 플레이어를 목표 위치로 이동
        /// </summary>
        private void MovePlayer(Vector3 targetPosition)
        {
            player.transform.DOMove(targetPosition, moveDuration);
        }

        /// <summary>
        /// 플레이어 애니메이션 상태 업데이트
        /// </summary>
        private void UpdateAnimationState(float moveMagnitude)
        {
            if (_playerAnimator != null)
            {
                _playerAnimator.SetFloat("Walk", moveMagnitude);
            }
        }

        /// <summary>
        /// 이동 중 공격 시도
        /// </summary>
        private void TryAttack(Vector3 moveDirection)
        {
            if (moveDirection.magnitude > 0.1f && !_isAttack)
            {
                PlayerAttack(moveDirection).Forget();
            }
        }

        /// <summary>
        /// 이동 방향에 따른 캐릭터 회전 처리
        /// </summary>
        private void UpdateCharacterRotation(Vector3 moveDirection)
        {
            if (moveDirection != Vector3.zero && playerCharactor != null)
            {
                float angle = Mathf.Atan2(moveDirection.y, moveDirection.x) * Mathf.Rad2Deg;
                float yRotation = (angle > 90 || angle < -90) ? 0f : 180f;
                playerCharactor.transform.rotation = Quaternion.Euler(0, yRotation, 0);
            }
        }

        /// <summary>
        /// 플레이어 공격 호출 
        /// </summary>
        /// <param name="attackAngle">공격 방향</param>
        private async UniTask PlayerAttack(Vector3 attackAngle)
        {
            _isAttack = true;
            playerCharactor.AttackAngle = attackAngle;
            playerCharactor.PlayState = PlayerBase.playerState.Attack;

            await UniTask.Delay(100);
            _isAttack = false;
        }

        #endregion

        #region 카메라 제어

        /// <summary>
        /// 카메라 추적 
        /// </summary>
        private void FallowCamera()
        {
            // playerCharactor, cameraTransform, mapRange가 모두 할당되었는지 확인
            if (playerCharactor == null || cameraTransform == null || mapRange == null)
            {
                // 필수 컴포넌트가 없으면 카메라 추적을 시도하지 않음
                return;
            }

            // 카메라가 맵 경계를 벗어나지 않도록 설정
            Vector3 cameraPosition = new Vector3(playerCharactor.transform.position.x,
                playerCharactor.transform.position.y, cameraTransform.transform.position.z);

            // 맵 범위의 경계를 가져옴
            Bounds mapBounds = mapRange.bounds;

            // 카메라의 절반 크기를 계산
            float cameraHalfWidth = cameraTransform.orthographicSize * cameraTransform.aspect;
            float cameraHalfHeight = cameraTransform.orthographicSize;

            // 맵 범위 내에서 카메라 위치를 클램프
            cameraPosition.x = Mathf.Clamp(cameraPosition.x, mapBounds.min.x + cameraHalfWidth,
                mapBounds.max.x - cameraHalfWidth);
            cameraPosition.y = Mathf.Clamp(cameraPosition.y, mapBounds.min.y + cameraHalfHeight,
                mapBounds.max.y - cameraHalfHeight);

            cameraTransform.transform.DOMove(cameraPosition, moveDuration);
        }

        #endregion
    }
}

using Cysharp.Threading.Tasks;
using UnityEngine;
using DG.Tweening;
using UnityEngine.UI;

namespace DogGuns_Games.vamsir
{
    public class VamPlayerControll : MonoBehaviour
    {

        //todo: 플레이어의 HP가 O 이하로 떨어지면 게임 오버 처리

        #region 필드 및 변수

        [Header("<color=green>Player Object")] [SerializeField]
        private GameObject player;

        [Header("<color=green>Player charactor Object")] [SerializeField]
        private PlayerBase playerCharactor;

        [Header("<color=green>Player HP_IU")] [SerializeField]
        private Slider playerHpSliderPrefab;

        private float _playerHpSliderValue = 0;

        private Animator _playerAnimator;

        [Header("<color=green>Joystick")] [SerializeField]
        private VariableJoystick variableJoystick;

        [Header("<color=green>camera")] [SerializeField]
        private Camera cameraTransform;

        [Header("<color=green>Move Duration")] [SerializeField]
        private float moveDuration = 0.1f;


        private Slider _playerHpSlider; // 인스턴스화된 슬라이더 참조 추가

        [Header("<color=green>Map Range")] [SerializeField]
        private SpriteRenderer mapRange;


        bool _isGameStart = false;

        bool _isAttack = false;

        #endregion

        #region Unity 라이프사이클

        private void Start()
        {
            PlayStateManager.OnGameStart += PlayerInit;
            PlayStateManager.OnGamePause += Pause;
            PlayStateManager.OnGameResume += Resume;
        }

        private void OnDestroy()
        {
            PlayStateManager.OnGameStart -= PlayerInit;
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
        }

        private void FixedUpdate()
        {
            if (_isGameStart)
            {
                PlayerMovement();
                FallowCamera();
                UpdatePlayerHpSlider();
            }
        }

        #endregion

        #region 게임 상태 관리

        private void PlayerInit()
        {
            // 캐릭터 스폰과의 레이스 컨디션을 피하기 위해 초기화 로직을 AssignCharacter로 이동했습니다.
            // OnGameStart 이벤트에서는 게임 시작 플래그만 설정합니다.
            _isGameStart = true;
        }

        /// <summary>
        /// VamserLikeGameManager가 플레이어 스폰 후 호출하여 캐릭터를 설정합니다.
        /// </summary>
        /// <param name="character">스폰된 플레이어 캐릭터</param>
        public void AssignCharacter(PlayerBase character)
        {
            if (playerCharactor == null && character != null)
            {
                playerCharactor = character;
                playerCharactor.transform.SetParent(player.gameObject.transform);
                _playerAnimator = playerCharactor.GetComponent<Animator>();
                cameraTransform = Camera.main;
                Set_playerHpSlider();
            }
        }

        private void Pause()
        {
            _isGameStart = false;
        }

        private void Resume()
        {
            _isGameStart = true;
        }

        #endregion

        #region UI 설정

        private void Set_playerHpSlider()
        {
            _playerHpSlider = Instantiate(playerHpSliderPrefab, player.transform);
            _playerHpSlider.transform.localPosition = new Vector3(0, -0.4f, 0);
            _playerHpSlider.maxValue = playerCharactor.Health;
            _playerHpSlider.value = playerCharactor.Health;
            _playerHpSliderValue = playerCharactor.Health;
        }

        private void UpdatePlayerHpSlider()
        {
            if (playerCharactor == null)
            {
                PlayerInit();
                return;
            }

            // 현재 체력 값이 이전 값과 다를 때만 슬라이더 업데이트
            if (_playerHpSlider != null && Mathf.Abs(_playerHpSliderValue - playerCharactor.Health) > 0.001f)
            {
                _playerHpSliderValue = playerCharactor.Health;
                _playerHpSlider.value = _playerHpSliderValue;

                // 게임 오버 처리는 PlayerBase의 Player_Hit에서 담당하므로 여기서는 제거
                // PlayerBase에서 Health <= 0일 때 자동으로 게임 오버 처리됨
            }
        }

        #endregion

        #region 플레이어 제어

        /// <summary>
        /// 플레이어 이동을 처리하는 메서드
        /// </summary>
        private void PlayerMovement()
        {
            // 플레이어 객체 유효성 검사
            if (player == null || playerCharactor == null)
            {
                // PlayerInit(); // 재귀 호출 및 로직 문제로 제거
                return;
            }

            // 이동 입력 및 위치 계산
            Vector3 moveDirection = GetJoystickInputDirection();
            Vector3 targetPosition = CalculateTargetPosition(moveDirection);

            // 실제 이동 처리
            MovePlayer(targetPosition);

            // 애니메이션 및 회전 처리
            UpdateAnimationState(moveDirection.magnitude);

            // 공격 처리
            TryAttack(moveDirection);

            // 캐릭터 회전 처리
            UpdateCharacterRotation(moveDirection);
        }

        /// <summary>
        /// 조이스틱 입력을 방향 벡터로 변환
        /// </summary>
        private Vector3 GetJoystickInputDirection()
        {
            return (Vector3.right * variableJoystick.Horizontal + Vector3.up * variableJoystick.Vertical);
        }

        /// <summary>
        /// 맵 범위를 고려한 목표 위치 계산
        /// </summary>
        private Vector3 CalculateTargetPosition(Vector3 moveDirection)
        {
            float deltaSpeed = playerCharactor.MoveSpeed * Time.deltaTime;
            Vector3 rawTargetPosition = player.transform.position + moveDirection * deltaSpeed;

            // 맵 경계 확인
            Bounds mapBounds = mapRange.bounds;

            // 맵 범위 내로 제한
            Vector3 clampedPosition = new Vector3(
                Mathf.Clamp(rawTargetPosition.x, mapBounds.min.x, mapBounds.max.x),
                Mathf.Clamp(rawTargetPosition.y, mapBounds.min.y, mapBounds.max.y),
                rawTargetPosition.z
            );

            return clampedPosition;
        }

        /// <summary>
        /// 플레이어를 목표 위치로 이동
        /// </summary>
        private void MovePlayer(Vector3 targetPosition)
        {
            player.transform.DOMove(targetPosition, moveDuration);
        }

        /// <summary>
        /// 플레이어 애니메이션 상태 업데이트
        /// </summary>
        private void UpdateAnimationState(float moveMagnitude)
        {
            if (_playerAnimator != null)
            {
                _playerAnimator.SetFloat("Walk", moveMagnitude);
            }
        }

        /// <summary>
        /// 이동 중 공격 시도
        /// </summary>
        private void TryAttack(Vector3 moveDirection)
        {
            if (moveDirection.magnitude > 0.1f && !_isAttack)
            {
                PlayerAttack(moveDirection).Forget();
            }
        }

        /// <summary>
        /// 이동 방향에 따른 캐릭터 회전 처리
        /// </summary>
        private void UpdateCharacterRotation(Vector3 moveDirection)
        {
            if (moveDirection != Vector3.zero && playerCharactor != null)
            {
                float angle = Mathf.Atan2(moveDirection.y, moveDirection.x) * Mathf.Rad2Deg;
                float yRotation = (angle > 90 || angle < -90) ? 0f : 180f;
                playerCharactor.transform.rotation = Quaternion.Euler(0, yRotation, 0);
            }
        }

        /// <summary>
        /// 플레이어 공격 호출 
        /// </summary>
        /// <param name="attackAngle">공격 방향</param>
        private async UniTask PlayerAttack(Vector3 attackAngle)
        {
            _isAttack = true;
            playerCharactor.AttackAngle = attackAngle;
            playerCharactor.PlayState = PlayerBase.playerState.Attack;

            await UniTask.Delay(100);
            _isAttack = false;
        }

        #endregion

        #region 카메라 제어

        /// <summary>
        /// 카메라 추적 
        /// </summary>
        private void FallowCamera()
        {
            // playerCharactor, cameraTransform, mapRange가 모두 할당되었는지 확인
            if (playerCharactor == null || cameraTransform == null || mapRange == null)
            {
                // 필수 컴포넌트가 없으면 카메라 추적을 시도하지 않음
                return;
            }

            // 카메라가 맵 경계를 벗어나지 않도록 설정
            Vector3 cameraPosition = new Vector3(playerCharactor.transform.position.x,
                playerCharactor.transform.position.y, cameraTransform.transform.position.z);

            // 맵 범위의 경계를 가져옴
            Bounds mapBounds = mapRange.bounds;

            // 카메라의 절반 크기를 계산
            float cameraHalfWidth = cameraTransform.orthographicSize * cameraTransform.aspect;
            float cameraHalfHeight = cameraTransform.orthographicSize;

            // 맵 범위 내에서 카메라 위치를 클램프
            cameraPosition.x = Mathf.Clamp(cameraPosition.x, mapBounds.min.x + cameraHalfWidth,
                mapBounds.max.x - cameraHalfWidth);
            cameraPosition.y = Mathf.Clamp(cameraPosition.y, mapBounds.min.y + cameraHalfHeight,
                mapBounds.max.y - cameraHalfHeight);

            cameraTransform.transform.DOMove(cameraPosition, moveDuration);
        }

        #endregion
    }
}

using Cysharp.Threading.Tasks;
using DG.Tweening;
using TMPro;
using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;

namespace DogGuns_Games.vamsir
{
    /// <summary>
    /// 뱀서라이크 게임의 기본 게임플레이 관리자
    /// </summary>
    public class VamserLikeGameManager : MonoBehaviour
    {
        #region 필드 및 변수

        private PlayerBase _spawnedPlayer;

        [Header("캐릭터 및 무기가 스폰 될시 부모 오브젝트")]
        [SerializeField] private GameObject inGameObjectParent;

        private readonly Vector3 _spawnPosition = Vector3.zero;

        [Header("옵션 팝업 매니저")]
        [SerializeField] private OptionPopupManager optionPopupManager;
        public SettingsData_oBJ settingsData;

        private ObjectPoolSpawner _objectPoolSpawner;
        private VamPlayerControll _vamPlayerControll;
        #endregion

        #region Unity 라이프사이클

        /// <summary>
        /// 컴포넌트 초기화 및 이벤트 구독
        /// </summary>
        /// <summary>
        /// 컴포넌트 초기화 및 이벤트 구독
        /// </summary>
        private void Awake()
        {
            _objectPoolSpawner = FindFirstObjectByType<ObjectPoolSpawner>();
            _vamPlayerControll = FindFirstObjectByType<VamPlayerControll>();

            PlayStateManager.OnGameStart += GameStart;
            PlayStateManager.OnGamePause += Pause;
            PlayStateManager.OnGameResume += Resume;
        }

        /// <summary>
        /// 이벤트 구독 해제
        /// </summary>
        private void OnDestroy()
        {
            PlayStateManager.OnGameStart -= GameStart;
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
        }


        #endregion

        #region 게임 상태 관리

        /// <summary>
        /// 게임 시작 이벤트 처리 (비동기로 변경)
        /// </summary>
        private async void GameStart()
        {
            PlayStateManager.instance.isPlay = true;
            PlayerDataManagerDontdesytoy.Instance.scritpableobjPlayerData.nowPlayMObkillCOunt = 0;

            SoundManager.PlaySound(Sound.BGM, SoundKeys.InGame, true);
            // 플레이어와 무기 스폰이 완료될 때까지 기다립니다.

            await SpawnPlayer();

            // 플레이어 스폰이 성공적으로 완료된 후에 몹 스포너를 활성화합니다.
            if (_spawnedPlayer != null && _objectPoolSpawner != null)
            {
                await _objectPoolSpawner.InitializeAndStartSpawning(_spawnedPlayer);
                Debug.Log("게임 시작: 플레이어 스폰 완료 후 몹 스포너 활성화");
            }
            else
            {
                Debug.LogError("플레이어 스폰에 실패했거나 ObjectPoolSpawner를 찾을 수 없어 게임을 시작할 수 없습니다.");
            }
        }

        /// <summary>
        /// 게임 일시정지 이벤트 처리
        /// </summary>
        private void Pause()
        {
            PlayStateManager.instance.isPlay = false;
            Debug.Log("게임 일시정지");
        }

        /// <summary>
        /// 게임 재개 이벤트 처리
        /// </summary>
        private void Resume()
        {
            PlayStateManager.instance.isPlay = true;
            Debug.Log("게임 재개");
        }

        /// <summary>
        /// 메뉴 팝업 열기와 게임 상태 변경
        /// </summary>
        public void Open_MenuPopUp(bool isPause)
        {
            PlayStateManager.instance.PlayState = isPause ? 
                PlayStateManager.GameState.Pause : 
                PlayStateManager.GameState.Resume;

            Debug.Log($"메뉴 팝업 {(isPause ? "열림" : "닫힘")}");
        }

        /// <summary>
        /// 옵션 팝업 열기
        /// </summary>
        public void Open_OptionPopUp()
        {
            if (optionPopupManager == null)
            {
                Debug.LogError("옵션 팝업 매니저가 설정되지 않았습니다.");
                return;
            }

            Instantiate(optionPopupManager);
            optionPopupManager.gameObject.SetActive(true);
            Debug.Log("옵션 팝업 열림");
        }

        #endregion

        #region 플레이어/무기 스폰 관리


        /// <summary>
        /// 현재 선택된 플레이어와 무기를 비동기적으로 스폰합니다. (반환 타입을 UniTask로 변경)
        /// </summary>
        private async UniTask SpawnPlayer()
        {
            if (!PlayStateManager.instance.isPlay || inGameObjectParent == null)
            {
                Debug.LogWarning("게임이 플레이 상태가 아니거나 부모 오브젝트가 설정되지 않았습니다.");
                return;
            }

            try
            {
                Weaphon_base spawnedWeapon = await SpawnSelectedWeapon();
                if (spawnedWeapon == null)
                {
                    Debug.LogError("무기 스폰에 실패하여 캐릭터를 스폰할 수 없습니다.");
                    return;
                }

                await SpawnSelectedCharacter(spawnedWeapon);
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"플레이어 또는 무기 스폰 중 예외 발생: {ex.Message}");
                _spawnedPlayer = null; // 실패 시 참조를 null로 설정
            }
        }

        /// <summary>
        /// 선택된 무기를 Addressable을 사용하여 스폰합니다.
        /// </summary>
        private async UniTask<Weaphon_base> SpawnSelectedWeapon()
        {
            int weaponIndex = PlayerDataManagerDontdesytoy.Instance.SelectWeaponIndex;
            string addressableKey = $"Weapon_{weaponIndex}"; // 무기 Addressable 주소 규칙

            try
            {
                GameObject weaponInstance = await Addressables.InstantiateAsync(addressableKey, _spawnPosition, Quaternion.identity, inGameObjectParent.transform).ToUniTask();
                if (weaponInstance != null)
                {
                    Debug.Log($"무기 스폰 성공: {addressableKey}");
                    return weaponInstance.GetComponent<Weaphon_base>();
                }
                return null;
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"Addressable 키 '{addressableKey}'를 가진 무기 스폰 중 예외 발생: {ex.Message}");
                return null;
            }
        }

        /// <summary>
        /// 선택된 캐릭터를 스폰하고 무기를 설정합니다.
        /// </summary>
        private async UniTask SpawnSelectedCharacter(Weaphon_base weaponToAssign)
        {
            int characterIndex = PlayerDataManagerDontdesytoy.Instance.SelectCharacterIndex;
            string addressableKey = $"Player_Character_{characterIndex}";

            try
            {
                GameObject characterInstance = await Addressables.InstantiateAsync(addressableKey, _spawnPosition, Quaternion.identity, inGameObjectParent.transform).ToUniTask();
                if (characterInstance != null)
                {
                    Debug.Log($"캐릭터 스폰 성공: {addressableKey}");
                    _spawnedPlayer = characterInstance.GetComponent<PlayerBase>();
                    if (_spawnedPlayer != null)
                    {
                        _spawnedPlayer.InitializeWeapon(weaponToAssign);
                        if (_vamPlayerControll != null)
                        {
                            _vamPlayerControll.AssignCharacter(_spawnedPlayer);
                        }
                        else
                        {
                            Debug.LogError("VamPlayerControll을 찾을 수 없습니다.");
                        }
                    }
                    else
                    {
                        Debug.LogError("스폰된 캐릭터에서 PlayerBase 컴포넌트를 찾을 수 없습니다.");
                    }
                }
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"Addressable 키 '{addressableKey}'를 가진 캐릭터 스폰 중 예외 발생: {ex.Message}");
                // 실패 시 _spawnedPlayer를 null로 설정
                _spawnedPlayer = null;
            }
        }


        /// <summary>
        /// 현재 스폰된 캐릭터와 무기를 변경
        /// </summary>
        public async void ChangeCharacterAndWeapon_Spawn()
        {
            if (inGameObjectParent == null)
            {
                Debug.LogError("인게임 오브젝트 부모가 설정되지 않았습니다.");
                return;
            }

            // 현재 캐릭터와 무기 제거
            for (int i = inGameObjectParent.transform.childCount - 1; i >= 0; i--)
            {
                Transform child = inGameObjectParent.transform.GetChild(i);
                // Addressables로 생성된 오브젝트는 Addressables.ReleaseInstance로 해제하는 것이 좋습니다.
                Addressables.ReleaseInstance(child.gameObject);
            }
            _spawnedPlayer = null; // 참조 제거

            // 새 캐릭터와 무기 스폰 (비동기 호출 및 대기)
            await SpawnPlayer();
            Debug.Log("캐릭터와 무기 변경 완료");
        }

        #endregion

        #region UI 효과 및 데이터 접근

        /// <summary>
        /// 웨이브 텍스트에 페이드 효과 적용
        /// </summary>
        public void WaveTextFadeEffect(TMP_Text mobWaveText)
        {
            if (mobWaveText == null)
            {
                Debug.LogError("웨이브 텍스트가 null입니다.");
                return;
            }

            // 페이드 인 효과
            mobWaveText.DOFade(1, 1)
                .SetEase(Ease.Linear)
                .OnComplete(() =>
                {
                    // 페이드 아웃 효과
                    mobWaveText.DOFade(0, 1)
                        .SetEase(Ease.Linear)
                        .SetDelay(1f);
                });
        }

        /// <summary>
        /// 현재 처치한 몹 수 반환
        /// </summary>
        public int Mob_Count()
        {
            return PlayerDataManagerDontdesytoy.Instance?.scritpableobjPlayerData?.nowPlayMObkillCOunt ?? 0;
        }

        /// <summary>
        /// 현재 몹 스폰 웨이브 반환
        /// </summary>
        public int MobSpawnWave()
        {
            return _objectPoolSpawner?.MobSpawnWave ?? 0;
        }


        /// <summary>
        /// 현재 플레이어 레벨 반환
        /// </summary>
        public float PlayerLevel()
        {
            if (_spawnedPlayer != null)
            {
                return _spawnedPlayer.Level;
            }

            Debug.LogWarning("스폰된 플레이어가 없어 레벨을 가져올 수 없습니다.");
            return 1; // 기본값 반환
        }

        /// <summary>
        /// 현재 플레이어의 경험치 반환
        /// </summary>
        public float GetPlayerCurrentExp()
        {
            if (_spawnedPlayer != null)
            {
                return _spawnedPlayer.CurrentExp;
            }

            return 0f;
        }

        /// <summary>
        /// 현재 플레이어의 최대 경험치 반환
        /// </summary>
        public float GetPlayerMaxExp()
        {
            if (_spawnedPlayer != null)
            {
                return _spawnedPlayer.MaxExp;
            }

            return 100f; // 기본값
        }

        /// <summary>
        /// 현재 플레이어의 경험치 진행률 반환 (0~1)
        /// </summary>
        public float GetPlayerExpProgress()
        {
            if (_spawnedPlayer != null)
            {
                return _spawnedPlayer.GetExpProgress();
            }

            return 0f;
        }

        /// <summary>
        /// 현재 코인 수 반환
        /// </summary>
        public int CoinCount()
        {
            return PlayerDataManagerDontdesytoy.Instance?.scritpableobjPlayerData?.currency1 ?? 0;
        }

        #endregion
    }
}

using Cysharp.Threading.Tasks;
using DG.Tweening;
using TMPro;
using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;

namespace DogGuns_Games.vamsir
{
    /// <summary>
    /// 뱀서라이크 게임의 기본 게임플레이 관리자
    /// </summary>
    public class VamserLikeGameManager : MonoBehaviour
    {
        #region 필드 및 변수

        private PlayerBase _spawnedPlayer;

        [Header("캐릭터 및 무기가 스폰 될시 부모 오브젝트")]
        [SerializeField] private GameObject inGameObjectParent;

        private readonly Vector3 _spawnPosition = Vector3.zero;

        [Header("옵션 팝업 매니저")]
        [SerializeField] private OptionPopupManager optionPopupManager;

        private ObjectPoolSpawner _objectPoolSpawner;
        private VamPlayerControll _vamPlayerControll;
        #endregion

        #region Unity 라이프사이클

        /// <summary>
        /// 컴포넌트 초기화 및 이벤트 구독
        /// </summary>
        /// <summary>
        /// 컴포넌트 초기화 및 이벤트 구독
        /// </summary>
        private void Awake()
        {
            _objectPoolSpawner = FindFirstObjectByType<ObjectPoolSpawner>();
            _vamPlayerControll = FindFirstObjectByType<VamPlayerControll>();

            PlayStateManager.OnGameStart += GameStart;
            PlayStateManager.OnGamePause += Pause;
            PlayStateManager.OnGameResume += Resume;
        }

        /// <summary>
        /// 이벤트 구독 해제
        /// </summary>
        private void OnDestroy()
        {
            PlayStateManager.OnGameStart -= GameStart;
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
        }


        #endregion

        #region 게임 상태 관리

        /// <summary>
        /// 게임 시작 이벤트 처리 (비동기로 변경)
        /// </summary>
        private async void GameStart()
        {
            PlayStateManager.instance.isPlay = true;
            PlayerDataManagerDontdesytoy.Instance.scritpableobjPlayerData.nowPlayMObkillCOunt = 0;

            SoundManager.PlaySound(Sound.BGM, SoundKeys.InGame, true);
            // 플레이어와 무기 스폰이 완료될 때까지 기다립니다.

            await SpawnPlayer();

            // 플레이어 스폰이 성공적으로 완료된 후에 몹 스포너를 활성화합니다.
            if (_spawnedPlayer != null && _objectPoolSpawner != null)
            {
                await _objectPoolSpawner.InitializeAndStartSpawning(_spawnedPlayer);
                Debug.Log("게임 시작: 플레이어 스폰 완료 후 몹 스포너 활성화");
            }
            else
            {
                Debug.LogError("플레이어 스폰에 실패했거나 ObjectPoolSpawner를 찾을 수 없어 게임을 시작할 수 없습니다.");
            }
        }

        /// <summary>
        /// 게임 일시정지 이벤트 처리
        /// </summary>
        private void Pause()
        {
            PlayStateManager.instance.isPlay = false;
            Debug.Log("게임 일시정지");
        }

        /// <summary>
        /// 게임 재개 이벤트 처리
        /// </summary>
        private void Resume()
        {
            PlayStateManager.instance.isPlay = true;
            Debug.Log("게임 재개");
        }

        /// <summary>
        /// 메뉴 팝업 열기와 게임 상태 변경
        /// </summary>
        public void Open_MenuPopUp(bool isPause)
        {
            PlayStateManager.instance.PlayState = isPause ? 
                PlayStateManager.GameState.Pause : 
                PlayStateManager.GameState.Resume;

            Debug.Log($"메뉴 팝업 {(isPause ? "열림" : "닫힘")}");
        }

        /// <summary>
        /// 옵션 팝업 열기
        /// </summary>
        public void Open_OptionPopUp()
        {
            if (optionPopupManager == null)
            {
                Debug.LogError("옵션 팝업 매니저가 설정되지 않았습니다.");
                return;
            }

            Instantiate(optionPopupManager);
            optionPopupManager.gameObject.SetActive(true);
            Debug.Log("옵션 팝업 열림");
        }

        #endregion

        #region 플레이어/무기 스폰 관리


        /// <summary>
        /// 현재 선택된 플레이어와 무기를 비동기적으로 스폰합니다. (반환 타입을 UniTask로 변경)
        /// </summary>
        private async UniTask SpawnPlayer()
        {
            if (!PlayStateManager.instance.isPlay || inGameObjectParent == null)
            {
                Debug.LogWarning("게임이 플레이 상태가 아니거나 부모 오브젝트가 설정되지 않았습니다.");
                return;
            }

            try
            {
                Weaphon_base spawnedWeapon = await SpawnSelectedWeapon();
                if (spawnedWeapon == null)
                {
                    Debug.LogError("무기 스폰에 실패하여 캐릭터를 스폰할 수 없습니다.");
                    return;
                }

                await SpawnSelectedCharacter(spawnedWeapon);
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"플레이어 또는 무기 스폰 중 예외 발생: {ex.Message}");
                _spawnedPlayer = null; // 실패 시 참조를 null로 설정
            }
        }

        /// <summary>
        /// 선택된 무기를 Addressable을 사용하여 스폰합니다.
        /// </summary>
        private async UniTask<Weaphon_base> SpawnSelectedWeapon()
        {
            int weaponIndex = PlayerDataManagerDontdesytoy.Instance.SelectWeaponIndex;
            string addressableKey = $"Weapon_{weaponIndex}"; // 무기 Addressable 주소 규칙

            try
            {
                GameObject weaponInstance = await Addressables.InstantiateAsync(addressableKey, _spawnPosition, Quaternion.identity, inGameObjectParent.transform).ToUniTask();
                if (weaponInstance != null)
                {
                    Debug.Log($"무기 스폰 성공: {addressableKey}");
                    return weaponInstance.GetComponent<Weaphon_base>();
                }
                return null;
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"Addressable 키 '{addressableKey}'를 가진 무기 스폰 중 예외 발생: {ex.Message}");
                return null;
            }
        }

        /// <summary>
        /// 선택된 캐릭터를 스폰하고 무기를 설정합니다.
        /// </summary>
        private async UniTask SpawnSelectedCharacter(Weaphon_base weaponToAssign)
        {
            int characterIndex = PlayerDataManagerDontdesytoy.Instance.SelectCharacterIndex;
            string addressableKey = $"Player_Character_{characterIndex}";

            try
            {
                GameObject characterInstance = await Addressables.InstantiateAsync(addressableKey, _spawnPosition, Quaternion.identity, inGameObjectParent.transform).ToUniTask();
                if (characterInstance != null)
                {
                    Debug.Log($"캐릭터 스폰 성공: {addressableKey}");
                    _spawnedPlayer = characterInstance.GetComponent<PlayerBase>();
                    if (_spawnedPlayer != null)
                    {
                        _spawnedPlayer.InitializeWeapon(weaponToAssign);
                        if (_vamPlayerControll != null)
                        {
                            _vamPlayerControll.AssignCharacter(_spawnedPlayer);
                        }
                        else
                        {
                            Debug.LogError("VamPlayerControll을 찾을 수 없습니다.");
                        }
                    }
                    else
                    {
                        Debug.LogError("스폰된 캐릭터에서 PlayerBase 컴포넌트를 찾을 수 없습니다.");
                    }
                }
            }
            catch (System.Exception ex)
            {
                Debug.LogError($"Addressable 키 '{addressableKey}'를 가진 캐릭터 스폰 중 예외 발생: {ex.Message}");
                // 실패 시 _spawnedPlayer를 null로 설정
                _spawnedPlayer = null;
            }
        }


        /// <summary>
        /// 현재 스폰된 캐릭터와 무기를 변경
        /// </summary>
        public async void ChangeCharacterAndWeapon_Spawn()
        {
            if (inGameObjectParent == null)
            {
                Debug.LogError("인게임 오브젝트 부모가 설정되지 않았습니다.");
                return;
            }

            // 현재 캐릭터와 무기 제거
            for (int i = inGameObjectParent.transform.childCount - 1; i >= 0; i--)
            {
                Transform child = inGameObjectParent.transform.GetChild(i);
                // Addressables로 생성된 오브젝트는 Addressables.ReleaseInstance로 해제하는 것이 좋습니다.
                Addressables.ReleaseInstance(child.gameObject);
            }
            _spawnedPlayer = null; // 참조 제거

            // 새 캐릭터와 무기 스폰 (비동기 호출 및 대기)
            await SpawnPlayer();
            Debug.Log("캐릭터와 무기 변경 완료");
        }

        #endregion

        #region UI 효과 및 데이터 접근

        /// <summary>
        /// 웨이브 텍스트에 페이드 효과 적용
        /// </summary>
        public void WaveTextFadeEffect(TMP_Text mobWaveText)
        {
            if (mobWaveText == null)
            {
                Debug.LogError("웨이브 텍스트가 null입니다.");
                return;
            }

            // 페이드 인 효과
            mobWaveText.DOFade(1, 1)
                .SetEase(Ease.Linear)
                .OnComplete(() =>
                {
                    // 페이드 아웃 효과
                    mobWaveText.DOFade(0, 1)
                        .SetEase(Ease.Linear)
                        .SetDelay(1f);
                });
        }

        /// <summary>
        /// 현재 처치한 몹 수 반환
        /// </summary>
        public int Mob_Count()
        {
            return PlayerDataManagerDontdesytoy.Instance?.scritpableobjPlayerData?.nowPlayMObkillCOunt ?? 0;
        }

        /// <summary>
        /// 현재 몹 스폰 웨이브 반환
        /// </summary>
        public int MobSpawnWave()
        {
            return _objectPoolSpawner?.MobSpawnWave ?? 0;
        }


        /// <summary>
        /// 현재 플레이어 레벨 반환
        /// </summary>
        public float PlayerLevel()
        {
            if (_spawnedPlayer != null)
            {
                return _spawnedPlayer.Level;
            }

            Debug.LogWarning("스폰된 플레이어가 없어 레벨을 가져올 수 없습니다.");
            return 1; // 기본값 반환
        }

        /// <summary>
        /// 현재 플레이어의 경험치 반환
        /// </summary>
        public float GetPlayerCurrentExp()
        {
            if (_spawnedPlayer != null)
            {
                return _spawnedPlayer.CurrentExp;
            }

            return 0f;
        }

        /// <summary>
        /// 현재 플레이어의 최대 경험치 반환
        /// </summary>
        public float GetPlayerMaxExp()
        {
            if (_spawnedPlayer != null)
            {
                return _spawnedPlayer.MaxExp;
            }

            return 100f; // 기본값
        }

        /// <summary>
        /// 현재 플레이어의 경험치 진행률 반환 (0~1)
        /// </summary>
        public float GetPlayerExpProgress()
        {
            if (_spawnedPlayer != null)
            {
                return _spawnedPlayer.GetExpProgress();
            }

            return 0f;
        }

        /// <summary>
        /// 현재 코인 수 반환
        /// </summary>
        public int CoinCount()
        {
            return PlayerDataManagerDontdesytoy.Instance?.scritpableobjPlayerData?.currency1 ?? 0;
        }

        #endregion
    }
}

using System.Collections.Generic;
using System.Threading;
using Cysharp.Threading.Tasks;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
using DG.Tweening;


namespace DogGuns_Games.vamsir
{
    public class VamserLikeUI : MonoBehaviour
    {
        #region 필드 및 변수

        [Header("<color=green>User Info UI")] [SerializeField]
        private TMP_Text LevelText;
        [SerializeField] private Slider playerLevelSlider;

        [Header("<color=green>Text UI")] [SerializeField]
        private TMP_Text mobWaveText;

        [SerializeField] private TMP_Text coinText;
        [SerializeField] private TMP_Text mobCountText;
        [SerializeField] private TMP_Text playerLevelText;
        [SerializeField] private Slider expSlider;


        [Header("<color=green>Menu UI")] [SerializeField]
        private Button menuBtn;

        [SerializeField] private GameObject menuPanel;
        [SerializeField] private Button settingBtn;
        [SerializeField] private Button exitBtn;
        public List<GameObject> weaponUIList = new List<GameObject>();
        public List<GameObject> juListUIList = new List<GameObject>();

        [Header("<color=green>GameOver UI")] [SerializeField]
        private GameObject gameOverPanel;

        [SerializeField] private Button gameOverExitBtn;
        [SerializeField] private Button gameOverRestartBtn;
        [SerializeField] private TMP_Text gameOverText;
        [SerializeField] private TMP_Text gameOverCoinText;
        [SerializeField] private TMP_Text gameOverWaveText;
        [SerializeField] private TMP_Text gameOverMobCountText;


        [Header("<color=green>조이스틱")] [SerializeField]
        private VariableJoystick variableJoystick;

        [SerializeField] private Transform joystickTransform;
        VamserLikeGameManager _gameManager;
        private CancellationTokenSource _cancellationTokenSource;

        #endregion

        #region Unity 라이프사이클

        private void Awake()
        {
            _gameManager = FindFirstObjectByType<VamserLikeGameManager>();
        }

        private void Start()
        {
            PlayStateManager.OnGameStart += GameStart;
            PlayStateManager.OnGamePause += Pause;
            PlayStateManager.OnGameResume += Resume;
            PlayStateManager.OnGameOver += ShowGameOverPopup;

            // 플레이어 경험치 이벤트 구독
            PlayerBase.OnExpChanged += OnPlayerExpChanged;
            PlayerBase.OnLevelUp += OnPlayerLevelUp;
        }

        private void OnDestroy()
        {
            _cancellationTokenSource?.Cancel();

            // 이벤트 구독 해제 추가
            PlayStateManager.OnGameStart -= GameStart;
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
            PlayStateManager.OnGameOver -= ShowGameOverPopup;

            // 플레이어 경험치 이벤트 구독 해제
            PlayerBase.OnExpChanged -= OnPlayerExpChanged;
            PlayerBase.OnLevelUp -= OnPlayerLevelUp;
        }

        #endregion

        #region 게임 상태 관리

        private void GameStart()
        {
            BtnSetting();
            JoystickSetting();
            SoundSetting(); // 사운드 설정 추가
            _cancellationTokenSource = new CancellationTokenSource();
            UpdateUI(_cancellationTokenSource.Token).Forget();
        }

        private void Pause()
        {
            joystickTransform.gameObject.SetActive(false);
        }

        private void Resume()
        {
            joystickTransform.gameObject.SetActive(true);
            JoystickSetting();
        }

        #endregion

        #region UI 설정 및 초기화

        private void JoystickSetting()
        {
            if (variableJoystick == null)
            {
                variableJoystick = FindFirstObjectByType<VariableJoystick>();
            }

            joystickTransform.localScale = new Vector3(_gameManager.settingsData.joystickSize,
                _gameManager.settingsData.joystickSize, 1);
            variableJoystick.SetMode((JoystickType)_gameManager.settingsData.joystickType);
            //todo : 조이스틱 위치 조정 필요 
            joystickTransform.position = new Vector3(_gameManager.settingsData.joystickPos.x,
                _gameManager.settingsData.joystickPos.y, 0);
        }


        private void SoundSetting()
        {
            SoundManager.Instance.LoadSoundSetting();
        }


        private void BtnSetting()
        {
            menuBtn.onClick.AddListener(PausePopUp);

            exitBtn.onClick.AddListener(PausePopUp);

            settingBtn.onClick.AddListener(() =>
            {
                _gameManager.Open_OptionPopUp();
            });

            // 게임 오버 버튼 설정
            gameOverExitBtn.onClick.AddListener(GameOverExit);
            gameOverRestartBtn.onClick.AddListener(GameOverRestart);
        }

        #endregion

        #region UI 이벤트 및 동작

        private void PausePopUp()
        {
            // 메뉴 패널의 현재 활성 상태의 반대로 설정합니다.
            bool isMenuPanelBecomingActive = !menuPanel.activeSelf;
            menuPanel.SetActive(isMenuPanelBecomingActive);

            // isMenuPanelBecomingActive 값에 따라 게임의 Pause/Resume 상태를 설정합니다.
            _gameManager.Open_MenuPopUp(isMenuPanelBecomingActive);

            // 메뉴 패널이 활성화되면 조이스틱을 비활성화하고, 그 반대의 경우도 마찬가지입니다.
            joystickTransform.gameObject.SetActive(!isMenuPanelBecomingActive);
        }

        private void GameOverExit()
        {
            // 게임 오버 패널을 비활성화하고, 로비 씬으로 이동
            gameOverPanel.SetActive(false);
            SceneLoader.Instance.LoadLobbyScene();
        }

        private void GameOverRestart()
        {
            // 게임 오버 패널을 비활성화하고, 게임을 다시 시작
            gameOverPanel.SetActive(false);
            // 씬을 다시 로드하여 게임을 재시작
            UnityEngine.SceneManagement.SceneManager.LoadScene(
                UnityEngine.SceneManagement.SceneManager.GetActiveScene().name);
        }

        #endregion

        #region 게임 오버

        /// <summary>
        /// 게임 오버 팝업을 표시합니다.
        /// </summary>
        public void ShowGameOverPopup()
        {
            // 게임 오버 UI 데이터 업데이트
            UpdateGameOverUI();

            // 게임 오버 패널 활성화
            gameOverPanel.SetActive(true);

            // 조이스틱 비활성화 및 위치/상태 초기화
            joystickTransform.gameObject.SetActive(false);
            if (variableJoystick != null)
            {
                   variableJoystick.OnPointerUp(null); // 입력 해제
            }

            // UI 업데이트 중지
            _cancellationTokenSource?.Cancel();
        }

        /// <summary>
        /// 게임 오버 UI의 텍스트들을 업데이트합니다.
        /// </summary>
        private void UpdateGameOverUI()
        {
            gameOverText.text = "Game Over";
            gameOverCoinText.text = $"Coins: {_gameManager.CoinCount()}";
            gameOverWaveText.text = $"Wave: {_gameManager.MobSpawnWave()}";
            gameOverMobCountText.text = $"Kills: {_gameManager.Mob_Count()}";
        }

        #endregion

        #region UI 업데이트

        private async UniTask UpdateUI(CancellationToken cancellationToken)
        {
            string lastWaveText = "";
            while (!cancellationToken.IsCancellationRequested)
            {
                string currentWaveText = $"Wave {_gameManager.MobSpawnWave()}";
                if (mobWaveText.text != currentWaveText)
                {
                    await WaveTextFadeEffect(currentWaveText);
                    lastWaveText = currentWaveText;
                }
                coinText.text = $"{_gameManager.CoinCount()}";
                mobCountText.text = $"{_gameManager.Mob_Count()}";
                playerLevelText.text = $"Lv. {_gameManager.PlayerLevel()}";
                // User Info UI 업데이트
                UpdatePlayerLevelUI();
                await UniTask.DelayFrame(1, PlayerLoopTiming.FixedUpdate, cancellationToken);
            }
        }

        // DOTween을 이용한 mobWaveText 페이드 인/아웃 효과
        private async UniTask WaveTextFadeEffect(string waveText)
        {
            mobWaveText.text = waveText;
            mobWaveText.alpha = 0f;
            mobWaveText.gameObject.SetActive(true);
            await mobWaveText.DOFade(1f, 0.5f).AsyncWaitForCompletion(); // 페이드 인
            await UniTask.Delay(1000); // 1초간 표시
            await mobWaveText.DOFade(0f, 0.5f).AsyncWaitForCompletion(); // 페이드 아웃
            mobWaveText.gameObject.SetActive(false);
        }

        /// <summary>
        /// 플레이어 레벨 UI를 업데이트합니다.
        /// </summary>
        private void UpdatePlayerLevelUI()
        {
            float currentLevel = _gameManager.PlayerLevel();
            LevelText.text = $"Lv. {currentLevel:F0}";

            // 실제 경험치 시스템 사용
            float expProgress = _gameManager.GetPlayerExpProgress();
            playerLevelSlider.value = expProgress;

            // 기존 expSlider도 같은 값으로 업데이트 (중복 슬라이더가 있는 경우)
            if (expSlider != null)
            {
                expSlider.value = expProgress;
            }
        }

        #endregion

        #region 플레이어 경험치 및 레벨 이벤트

        /// <summary>
        /// 플레이어 경험치가 변경되었을 때 호출되는 메서드입니다.
        /// </summary>
        private void OnPlayerExpChanged(float currentExp, float maxExp)
        {
            // 실시간으로 경험치 UI 업데이트
            UpdatePlayerLevelUI();

            // 디버그 로그 (선택사항)
            Debug.Log($"경험치 UI 업데이트: {currentExp:F1}/{maxExp:F1} ({(currentExp/maxExp)*100:F1}%)");
        }

        /// <summary>
        /// 플레이어 레벨업 시 호출되는 메서드입니다.
        /// </summary>
        private void OnPlayerLevelUp(float newLevel)
        {
            // 레벨업 시 UI 업데이트
            UpdatePlayerLevelUI();

            // 레벨업 축하 효과 (선택사항)
            ShowLevelUpEffect(newLevel);

            Debug.Log($"레벨업 UI 업데이트: 새 레벨 {newLevel}");
        }

        /// <summary>
        /// 레벨업 시 시각적 효과를 표시합니다.
        /// </summary>
        private void ShowLevelUpEffect(float newLevel)
        {
            // 레벨 텍스트에 간단한 효과 적용 (선택사항)
            if (LevelText != null)
            {
                // 크기 변화 효과 (DOTween 사용)
                LevelText.transform.localScale = Vector3.one * 1.2f;
                LevelText.transform.DOScale(Vector3.one, 0.3f)
                    .SetEase(Ease.OutBack);

                // 색상 변화 효과 (DOTween 사용)
                Color originalColor = LevelText.color;
                LevelText.color = Color.yellow;
                LevelText.DOColor(originalColor, 1f);
            }
        }

        #endregion
    }
}

using System.Collections.Generic;
using System.Threading;
using Cysharp.Threading.Tasks;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
using DG.Tweening;


namespace DogGuns_Games.vamsir
{
    public class VamserLikeUI : MonoBehaviour
    {
        #region 필드 및 변수

        [Header("<color=green>User Info UI")] [SerializeField]
        private TMP_Text LevelText;
        [SerializeField] private Slider playerLevelSlider;

        [Header("<color=green>Text UI")] [SerializeField]
        private TMP_Text mobWaveText;

        [SerializeField] private TMP_Text coinText;
        [SerializeField] private TMP_Text mobCountText;
        [SerializeField] private TMP_Text playerLevelText;
        [SerializeField] private Slider expSlider;


        [Header("<color=green>Menu UI")] [SerializeField]
        private Button menuBtn;

        [SerializeField] private GameObject menuPanel;
        [SerializeField] private Button settingBtn;
        [SerializeField] private Button exitBtn;
        public List<GameObject> weaponUIList = new List<GameObject>();
        public List<GameObject> juListUIList = new List<GameObject>();

        [Header("<color=green>GameOver UI")] [SerializeField]
        private GameObject gameOverPanel;

        [SerializeField] private Button gameOverExitBtn;
        [SerializeField] private Button gameOverRestartBtn;
        [SerializeField] private TMP_Text gameOverText;
        [SerializeField] private TMP_Text gameOverCoinText;
        [SerializeField] private TMP_Text gameOverWaveText;
        [SerializeField] private TMP_Text gameOverMobCountText;


        [Header("<color=green>조이스틱")] [SerializeField]
        private VariableJoystick variableJoystick;

        [SerializeField] private Transform joystickTransform;
        VamserLikeGameManager _gameManager;
        private CancellationTokenSource _cancellationTokenSource;

        #endregion

        #region Unity 라이프사이클

        private void Awake()
        {
            _gameManager = FindFirstObjectByType<VamserLikeGameManager>();
        }

        private void Start()
        {
            PlayStateManager.OnGameStart += GameStart;
            PlayStateManager.OnGamePause += Pause;
            PlayStateManager.OnGameResume += Resume;
            PlayStateManager.OnGameOver += ShowGameOverPopup;

            // 플레이어 경험치 이벤트 구독
            PlayerBase.OnExpChanged += OnPlayerExpChanged;
            PlayerBase.OnLevelUp += OnPlayerLevelUp;
        }

        private void OnDestroy()
        {
            _cancellationTokenSource?.Cancel();

            // 이벤트 구독 해제 추가
            PlayStateManager.OnGameStart -= GameStart;
            PlayStateManager.OnGamePause -= Pause;
            PlayStateManager.OnGameResume -= Resume;
            PlayStateManager.OnGameOver -= ShowGameOverPopup;

            // 플레이어 경험치 이벤트 구독 해제
            PlayerBase.OnExpChanged -= OnPlayerExpChanged;
            PlayerBase.OnLevelUp -= OnPlayerLevelUp;
        }

        #endregion

        #region 게임 상태 관리

        private void GameStart()
        {
            BtnSetting();
            JoystickSetting();
            SoundSetting(); // 사운드 설정 추가
            _cancellationTokenSource = new CancellationTokenSource();
            UpdateUI(_cancellationTokenSource.Token).Forget();
        }

        private void Pause()
        {
            joystickTransform.gameObject.SetActive(false);
        }

        private void Resume()
        {
            joystickTransform.gameObject.SetActive(true);
            JoystickSetting();
        }

        #endregion

        #region UI 설정 및 초기화

        private void JoystickSetting()
        {
            if (variableJoystick == null)
            {
                variableJoystick = FindFirstObjectByType<VariableJoystick>();
            }

            if (SoundManager.Instance == null)
            {
                Debug.LogError("SoundManager.Instance가 null입니다. 씬에 SoundManager가 배치되어 있는지 확인하세요.");
                return;
            }
            var settingsData = SoundManager.Instance.settingsData;
            if (settingsData == null)
            {
                Debug.LogError("SoundManager의 settingsData가 null입니다. 인스펙터에서 할당되어 있는지 확인하세요.");
                return;
            }
            joystickTransform.localScale = new Vector3(settingsData.joystickSize,
                settingsData.joystickSize, 1);
            variableJoystick.SetMode((JoystickType)settingsData.joystickType);
            //todo : 조이스틱 위치 조정 필요 
            joystickTransform.position = new Vector3(settingsData.joystickPos.x,
                settingsData.joystickPos.y, 0);
        }


        private void SoundSetting()
        {
            SoundManager.Instance.LoadSoundSetting();
        }


        private void BtnSetting()
        {
            menuBtn.onClick.AddListener(PausePopUp);

            exitBtn.onClick.AddListener(PausePopUp);

            settingBtn.onClick.AddListener(() =>
            {
                _gameManager.Open_OptionPopUp();
            });

            // 게임 오버 버튼 설정
            gameOverExitBtn.onClick.AddListener(GameOverExit);
            gameOverRestartBtn.onClick.AddListener(GameOverRestart);
        }

        #endregion

        #region UI 이벤트 및 동작

        private void PausePopUp()
        {
            // 메뉴 패널의 현재 활성 상태의 반대로 설정합니다.
            bool isMenuPanelBecomingActive = !menuPanel.activeSelf;
            menuPanel.SetActive(isMenuPanelBecomingActive);

            // isMenuPanelBecomingActive 값에 따라 게임의 Pause/Resume 상태를 설정합니다.
            _gameManager.Open_MenuPopUp(isMenuPanelBecomingActive);

            // 메뉴 패널이 활성화되면 조이스틱을 비활성화하고, 그 반대의 경우도 마찬가지입니다.
            joystickTransform.gameObject.SetActive(!isMenuPanelBecomingActive);
        }

        private void GameOverExit()
        {
            // 게임 오버 패널을 비활성화하고, 로비 씬으로 이동
            gameOverPanel.SetActive(false);
            SceneLoader.Instance.LoadLobbyScene();
        }

        private void GameOverRestart()
        {
            // 게임 오버 패널을 비활성화하고, 게임을 다시 시작
            gameOverPanel.SetActive(false);
            // 씬을 다시 로드하여 게임을 재시작
            UnityEngine.SceneManagement.SceneManager.LoadScene(
                UnityEngine.SceneManagement.SceneManager.GetActiveScene().name);
        }

        #endregion

        #region 게임 오버

        /// <summary>
        /// 게임 오버 팝업을 표시합니다.
        /// </summary>
        public void ShowGameOverPopup()
        {
            // 게임 오버 UI 데이터 업데이트
            UpdateGameOverUI();

            // 게임 오버 패널 활성화
            gameOverPanel.SetActive(true);

            // 조이스틱 비활성화 및 위치/상태 초기화
            joystickTransform.gameObject.SetActive(false);
            if (variableJoystick != null)
            {
                   variableJoystick.OnPointerUp(null); // 입력 해제
            }

            // UI 업데이트 중지
            _cancellationTokenSource?.Cancel();
        }

        /// <summary>
        /// 게임 오버 UI의 텍스트들을 업데이트합니다.
        /// </summary>
        private void UpdateGameOverUI()
        {
            gameOverText.text = "Game Over";
            gameOverCoinText.text = $"Coins: {_gameManager.CoinCount()}";
            gameOverWaveText.text = $"Wave: {_gameManager.MobSpawnWave()}";
            gameOverMobCountText.text = $"Kills: {_gameManager.Mob_Count()}";
        }

        #endregion

        #region UI 업데이트

        private async UniTask UpdateUI(CancellationToken cancellationToken)
        {
            string lastWaveText = "";
            while (!cancellationToken.IsCancellationRequested)
            {
                string currentWaveText = $"Wave {_gameManager.MobSpawnWave()}";
                if (mobWaveText.text != currentWaveText)
                {
                    await WaveTextFadeEffect(currentWaveText);
                    lastWaveText = currentWaveText;
                }
                coinText.text = $"{_gameManager.CoinCount()}";
                mobCountText.text = $"{_gameManager.Mob_Count()}";
                playerLevelText.text = $"Lv. {_gameManager.PlayerLevel()}";
                // User Info UI 업데이트
                UpdatePlayerLevelUI();
                await UniTask.DelayFrame(1, PlayerLoopTiming.FixedUpdate, cancellationToken);
            }
        }

        // DOTween을 이용한 mobWaveText 페이드 인/아웃 효과
        private async UniTask WaveTextFadeEffect(string waveText)
        {
            mobWaveText.text = waveText;
            mobWaveText.alpha = 0f;
            mobWaveText.gameObject.SetActive(true);
            await mobWaveText.DOFade(1f, 0.5f).AsyncWaitForCompletion(); // 페이드 인
            await UniTask.Delay(1000); // 1초간 표시
            await mobWaveText.DOFade(0f, 0.5f).AsyncWaitForCompletion(); // 페이드 아웃
            mobWaveText.gameObject.SetActive(false);
        }

        /// <summary>
        /// 플레이어 레벨 UI를 업데이트합니다.
        /// </summary>
        private void UpdatePlayerLevelUI()
        {
            float currentLevel = _gameManager.PlayerLevel();
            LevelText.text = $"Lv. {currentLevel:F0}";

            // 실제 경험치 시스템 사용
            float expProgress = _gameManager.GetPlayerExpProgress();
            playerLevelSlider.value = expProgress;

            // 기존 expSlider도 같은 값으로 업데이트 (중복 슬라이더가 있는 경우)
            if (expSlider != null)
            {
                expSlider.value = expProgress;
            }
        }

        #endregion

        #region 플레이어 경험치 및 레벨 이벤트

        /// <summary>
        /// 플레이어 경험치가 변경되었을 때 호출되는 메서드입니다.
        /// </summary>
        private void OnPlayerExpChanged(float currentExp, float maxExp)
        {
            // 실시간으로 경험치 UI 업데이트
            UpdatePlayerLevelUI();

            // 디버그 로그 (선택사항)
            Debug.Log($"경험치 UI 업데이트: {currentExp:F1}/{maxExp:F1} ({(currentExp/maxExp)*100:F1}%)");
        }

        /// <summary>
        /// 플레이어 레벨업 시 호출되는 메서드입니다.
        /// </summary>
        private void OnPlayerLevelUp(float newLevel)
        {
            // 레벨업 시 UI 업데이트
            UpdatePlayerLevelUI();

            // 레벨업 축하 효과 (선택사항)
            ShowLevelUpEffect(newLevel);

            Debug.Log($"레벨업 UI 업데이트: 새 레벨 {newLevel}");
        }

        /// <summary>
        /// 레벨업 시 시각적 효과를 표시합니다.
        /// </summary>
        private void ShowLevelUpEffect(float newLevel)
        {
            // 레벨 텍스트에 간단한 효과 적용 (선택사항)
            if (LevelText != null)
            {
                // 크기 변화 효과 (DOTween 사용)
                LevelText.transform.localScale = Vector3.one * 1.2f;
                LevelText.transform.DOScale(Vector3.one, 0.3f)
                    .SetEase(Ease.OutBack);

                // 색상 변화 효과 (DOTween 사용)
                Color originalColor = LevelText.color;
                LevelText.color = Color.yellow;
                LevelText.DOColor(originalColor, 1f);
            }
        }

        #endregion
    }
}

using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

public class JoyStickPosDragandDrop : MonoBehaviour, IDragHandler, IEndDragHandler, IPointerDownHandler
{
  [SerializeField]  float offsetY = 1000f;
    private RectTransform rectTransform;
    private Canvas canvas;
    private CanvasScaler canvasScaler;
    private Vector2 originalLocalPointerPosition;
    private Vector2 dragOffset;
    private float minX;
    private float maxX;
    private float minY;
    private float maxY;
    private void Awake()
    {
        rectTransform = GetComponent<RectTransform>();
        canvas = GetComponentInParent<Canvas>();
        canvasScaler = canvas != null ? canvas.GetComponentInParent<CanvasScaler>() : null;
    }

    public void OnPointerDown(PointerEventData eventData)
    {
        if (canvas == null || rectTransform == null) return;
        Vector2 localPointerPosition;
        if (RectTransformUtility.ScreenPointToLocalPointInRectangle(
            canvas.transform as RectTransform,
            eventData.position,
            eventData.pressEventCamera,
            out localPointerPosition))
        {
            dragOffset = rectTransform.anchoredPosition - localPointerPosition;
        }
    }

    public void OnDrag(PointerEventData eventData)
    {
        if (canvas == null || rectTransform == null) return;
        Vector2 localPointerPosition;
        if (!RectTransformUtility.ScreenPointToLocalPointInRectangle(
            canvas.transform as RectTransform,
            eventData.position,
            eventData.pressEventCamera,
            out localPointerPosition)) return;

        rectTransform.anchoredPosition = ClampToCanvas(localPointerPosition + dragOffset);
    }

    public void OnEndDrag(PointerEventData eventData)
    {
        if (canvas == null || rectTransform == null) return;
        rectTransform.anchoredPosition = ClampToCanvas(rectTransform.anchoredPosition);
    }

    private Vector2 ClampToCanvas(Vector2 position)
    {
        if canvas == null || rectTransform == null) return position;
        RectTransform canvasRect = canvas.GetComponent<RectTransform>();
        if (canvasRect == null) return position;

        minX = -canvasRect.rect.width * canvasRect.pivot.x + rectTransform.rect.width * rectTransform.pivot.x;
        maxX = canvasRect.rect.width * canvasRect.pivot.x - rectTransform.rect.width * rectTransform.pivot.x;
        minY = -canvasRect.rect.height * canvasRect.pivot.y + rectTransform.rect.height * rectTransform.pivot.y + offsetY;
        maxY = canvasRect.rect.height * canvasRect.pivot.y - rectTransform.rect.height * rectTransform.pivot.y + offsetY;
        position.x = Mathf.Clamp(position.x, minX, maxX);
        position.y = Mathf.Clamp(position.y, minY, maxY);
        return position;
    }

    private void OnDrawGizmos()
    {
        if (canvas == null) return;
        RectTransform canvasRect = canvas.GetComponent<RectTransform>();
        if (canvasRect == null) return;
        Gizmos.color = Color.red;
        Gizmos.DrawWireCube(canvasRect.transform.position, canvasRect.rect.size);
    }

}

